#include "PrinterOrigin.hpp"

#include "libslic3r/BoundingBox.hpp"

namespace Slic3r::GUI::JusPrin::Printers {

bool is_named_printer(const Preset& preset) { return preset.type == Preset::TYPE_PRINTER && preset.is_user() && preset.is_visible; }

bool printer_from_file(const Preset& preset) { return !preset.is_default && !is_named_printer(preset); }

std::optional<BedSize> bed_size(const DynamicPrintConfig& config)
{
    const auto* area = config.option<ConfigOptionPoints>("printable_area");
    if (area == nullptr || area->values.size() < 3)
        return std::nullopt;
    const BoundingBoxf box(area->values);
    const Vec2d size = box.size();
    if (size.x() <= 0. || size.y() <= 0.)
        return std::nullopt;
    return BedSize{size.x(), size.y()};
}

} // namespace Slic3r::GUI::JusPrin::Printers
